import React, { useState, useEffect } from 'react';
import TaskForm from './components/TaskForm';
import TaskList from './components/TaskList';
import StatsChart from './components/StatsChart';
import Chatbot from './components/Chatbot';
import Hero from './components/Hero';
import ThemeToggle from './components/ThemeToggle';
import TechStack from './components/TechStack';
import Services from './components/Services';
import './App.css';

function App() {
  const [tasks, setTasks] = useState(() => {
    const savedTasks = localStorage.getItem('prodtrack_tasks');
    return savedTasks ? JSON.parse(savedTasks) : [];
  });

  const [theme, setTheme] = useState(() => {
    return localStorage.getItem('prodtrack_theme') || 'cyber';
  });

  const [filter, setFilter] = useState('all');
  const [mousePos, setMousePos] = useState({ x: 0, y: 0 });

  useEffect(() => {
    const handleMouseMove = (e) => {
      setMousePos({ x: e.clientX, y: e.clientY });
    };
    window.addEventListener('mousemove', handleMouseMove);
    return () => window.removeEventListener('mousemove', handleMouseMove);
  }, []);

  useEffect(() => {
    document.documentElement.setAttribute('data-theme', theme);
    localStorage.setItem('prodtrack_theme', theme);
  }, [theme]);

  useEffect(() => {
    localStorage.setItem('prodtrack_tasks', JSON.stringify(tasks));
  }, [tasks]);

  const addTask = (taskData) => {
    const newTask = {
      id: Date.now().toString(),
      text: taskData.text,
      priority: taskData.priority || 'Medium',
      category: taskData.category || 'General',
      completed: false,
      createdAt: new Date().toISOString(),
    };
    setTasks([...tasks, newTask]);
  };

  const toggleComplete = (id) => {
    setTasks(prevTasks =>
      prevTasks.map(task =>
        task.id === id ? { ...task, completed: !task.completed } : task
      )
    );
  };

  const deleteTask = (id) => {
    setTasks(prevTasks => prevTasks.filter(task => task.id !== id));
  };

  const setReorderedTasks = (reorderedTasks) => {
    setTasks(reorderedTasks);
  };

  const getFilteredTasks = () => {
    let filtered = tasks;
    if (filter === 'active') filtered = filtered.filter(task => !task.completed);
    else if (filter === 'completed') filtered = filtered.filter(task => task.completed);
    return filtered;
  };

  return (
    <div className="App">
      <div
        className="cursor-glow"
        style={{ left: mousePos.x, top: mousePos.y }}
      />

      <header className="app-header">
        <div className="logo-container">
          <h1 className="app-title">Creator.Collective</h1>
        </div>
        <div className="header-actions">
          <ThemeToggle currentTheme={theme} setTheme={setTheme} />
          <div className="header-stats">
            <span className="stats-badge">
              {tasks.filter(t => t.completed).length} / {tasks.length} Shipped
            </span>
          </div>
        </div>
      </header>

      <main className="app-main">
        <Hero />

        <Services />

        <section className="roadmap-section">
          <span className="section-label">Real-time Project Roadmap</span>
          <TaskForm addTask={addTask} />

          <div className="filter-buttons">
            <button className={`filter-btn ${filter === 'all' ? 'active' : ''}`} onClick={() => setFilter('all')}>Timeline</button>
            <button className={`filter-btn ${filter === 'active' ? 'active' : ''}`} onClick={() => setFilter('active')}>In Progress</button>
            <button className={`filter-btn ${filter === 'completed' ? 'active' : ''}`} onClick={() => setFilter('completed')}>Launched</button>
          </div>

          <TaskList
            tasks={getFilteredTasks()}
            toggleComplete={toggleComplete}
            deleteTask={deleteTask}
            setTasks={setReorderedTasks}
          />
        </section>

        <StatsChart tasks={tasks} />
        <TechStack />
      </main>

      <Chatbot />
    </div>
  );
}

export default App;
